import sys
import subprocess
import requests
import re
from typing import Optional

def render_expr(expr: str) -> Optional[str]:
    try:
        return str(eval(expr))
    except:
        return ""

def render_cmd(cmd: str) -> Optional[str]:
    try:
        result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
        return result.stdout + result.stderr
    except subprocess.CalledProcessError:
        return ""

def render_url(url: str) -> Optional[str]:
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.text
    except:
        return ""

def replace_placeholders(template: str) -> str:
    def replace_expr(match):
        expr = match.group(1)
        return render_expr(expr) or ""

    def replace_cmd(match):
        cmd = match.group(1)
        return render_cmd(cmd) or ""

    def replace_url(match):
        url = match.group(1)
        return render_url(url) or ""

    template = re.sub(r'\{\{(expr:([^}]+))\}\}', replace_expr, template)
    template = re.sub(r'\{\{(cmd:([^}]+))\}\}', replace_cmd, template)
    template = re.sub(r'\{\{(url:([^}]+))\}\}', replace_url, template)
    return template

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python render.py <template_file>", file=sys.stderr)
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        template = f.read()

    print(replace_placeholders(template))

import sys
import subprocess
import requests
import re
from typing import Optional, Tuple

def evaluate_expr(expr: str) -> Optional[str]:
    try:
        return str(eval(expr))
    except:
        return ""

def run_cmd(cmd: str) -> Optional[str]:
    try:
        result = subprocess.run(cmd, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout + result.stderr
    except:
        return ""

def fetch_url(url: str) -> Optional[str]:
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except:
        return ""

def render_template(template_path: str) -> str:
    with open(template_path, 'r') as f:
        content = f.read()

    def replace_placeholder(match):
        kind = match.group(1)
        value = match.group(2).strip('"')

        if kind == 'expr':
            return evaluate_expr(value)
        elif kind == 'cmd':
            return run_cmd(value)
        elif kind == 'url':
            return fetch_url(value)
        return ""

    pattern = re.compile(r'\{\{\s*(expr|cmd|url)\s*:\s*(.*?)\s*\}\}')
    return pattern.sub(replace_placeholder, content)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python render.py <template_file>", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    print(render_template(template_path))

import sys
import re
import subprocess
import requests

def evaluate_expression(expr):
    try:
        return str(eval(expr))
    except Exception:
        return ''

def execute_command(cmd):
    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
        return result.stdout + result.stderr
    except Exception:
        return ''

def fetch_url(url):
    try:
        response = requests.get(url)
        return response.text
    except Exception:
        return ''

def render_template(template_path):
    with open(template_path, 'r') as file:
        content = file.read()

    # Replace expressions
    content = re.sub(r'\{\{expr:(.*?)\}\}', lambda m: evaluate_expression(m.group(1).strip()), content)
    # Replace commands
    content = re.sub(r'\{\{cmd:(.*?)\}\}', lambda m: execute_command(m.group(1).strip()), content)
    # Replace URLs
    content = re.sub(r'\{\{url:(.*?)\}\}', lambda m: fetch_url(m.group(1).strip()), content)

    return content

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python render.py <template_path>')
        sys.exit(1)

    template_path = sys.argv[1]
    rendered_content = render_template(template_path)
    print(rendered_content)
